    public static function for_offer($id,$lock=false) { global $wpdb;return $wpdb->get_row($wpdb->prepare('SELECT * FROM '.self::table('occurrences').' WHERE offer_id=%d'.($lock?' FOR UPDATE':''),$id)); }
