        if (!self::agency()) { $roles=Auth::organization_roles();$placeholders=implode(',',array_fill(0,count($roles),'%s'));$where='((e.org_id=0 AND e.owner_id=%d) OR (e.org_id>0 AND EXISTS (SELECT 1 FROM '.DB::table('memberships').' m INNER JOIN '.DB::table('organizations')." o ON o.id=m.org_id WHERE m.org_id=e.org_id AND m.user_id=%d AND m.status='active' AND o.status IN ('active','approved') AND m.role IN ($placeholders))))";$args=array_merge([get_current_user_id(),get_current_user_id()],$roles); }
        $sql="SELECT COUNT(*) FROM $table e WHERE $where";$total=(int)$wpdb->get_var($args?$wpdb->prepare($sql,$args):$sql);$query="SELECT e.* FROM $table e WHERE $where ORDER BY e.created_at DESC,e.id LIMIT 25 OFFSET %d";$args[]=($page-1)*25;$rows=$wpdb->get_results($wpdb->prepare($query,$args));if ($rows===null||$wpdb->last_error!=='') return self::error('atlas_event_storage','Event list unavailable.','فهرست رویداد در دسترس نیست.',503);return ['items'=>$rows,'total'=>$total,'page'=>$page,'limit'=>25];
