        global $wpdb;if (!is_user_logged_in()) return [];$page=min(100000,max(1,(int)$page));$rows=$wpdb->get_results($wpdb->prepare('SELECT DISTINCT c.id,c.revision,c.kind,c.payload,c.created_at,o.offer_id FROM '.self::table('changes').' c INNER JOIN '.self::table('occurrences').' o ON o.id=c.occurrence_id INNER JOIN '.DB::table('bookings').' b ON b.offer_id=o.offer_id WHERE b.user_id=%d ORDER BY c.created_at DESC,c.id LIMIT 25 OFFSET %d',get_current_user_id(),($page-1)*25),ARRAY_A);$out=[];foreach ($rows?:[] as $row) { $data=json_decode($row['payload'],true);unset($data['reason']);$row['notice']=$data;unset($row['payload']);$out[]=$row; }return $out;
    }
    private static function credential($occ,$booking,$index) { $data='1.'.$occ.'.'.$booking.'.'.$index;return $data.'.'.hash_hmac('sha256',$data,wp_salt('auth')); }
    public static function can_scan($occ) {
        if (self::agency()) return true;if (!is_user_logged_in()||!current_user_can('atlas_manage_records')) return false;$config=json_decode($occ->payload,true);return in_array(get_current_user_id(),$config['checkin_staff']??[],true)&&((int)$occ->org_id===0||Auth::role_allows((int)$occ->org_id,'write'));
    }
    public static function validate_checkin($valid,$booking,$offerId,$body) {
        if ($valid!==true) return $valid;$occ=self::for_offer($offerId,true);if (!$occ) return true;$config=json_decode($occ->payload,true);return self::can_scan($occ)&&$occ->state==='scheduled'&&DB::now()>=($config['checkin_open_at']??'')&&DB::now()<($config['checkin_close_at']??'')?true:self::error('atlas_event_checkin_closed','Assigned staff and the configured check-in window are required.','کارکنان تعیین‌شده و مهلت پذیرش پیکربندی‌شده لازم است.',409);
    }
    public static function credentials($bookingId) {
        global $wpdb;$booking=Atlas\Core\Booking::get($bookingId,get_current_user_id());if (is_wp_error($booking)||$booking['status']!=='confirmed') return self::error('atlas_not_found','Confirmed reservation unavailable.','رزرو تأییدشده در دسترس نیست.',404);$occ=self::for_offer($booking['offer_id']);if (!$occ||$occ->state!=='scheduled') return self::error('atlas_event_unavailable','Event is not available for attendance.','رویداد برای حضور در دسترس نیست.',409);$tokens=[];for ($index=1;$index<=$booking['quantity'];$index++) $tokens[]=['attendee_index'=>$index,'reference'=>self::credential($occ->id,$bookingId,$index)];return ['occurrence_id'=>$occ->id,'credentials'=>$tokens,'contains_personal_names'=>false];
    }
    public static function scan(array $body) {
        global $wpdb;if (!is_user_logged_in()||!current_user_can('atlas_manage_records')) return self::error('atlas_forbidden','Assigned check-in permission required.','دسترسی کارکنان پذیرش لازم است.',403);if (array_diff(array_keys($body),['reference','idempotency_key'])||!is_string($body['reference']??null)||strlen($body['reference'])>200||!is_string($body['idempotency_key']??null)||!preg_match('/^[A-Za-z0-9._:-]{8,128}$/D',$body['idempotency_key'])) return self::error('atlas_invalid_event','Attendance reference and request key required.','شناسه حضور و کلید درخواست لازم است.');$parts=explode('.',$body['reference']);if (count($parts)!==5||$parts[0]!=='1'||!self::uuid($parts[1])||!self::uuid($parts[2])||!ctype_digit($parts[3])||strlen($parts[3])>4||!hash_equals(self::credential($parts[1],$parts[2],(int)$parts[3]),$body['reference'])) return self::error('atlas_invalid_event','Invalid signed attendee reference.','شناسه امضاشده شرکت‌کننده معتبر نیست.');
        $assigned=self::occurrence($parts[1]);if (!$assigned||!self::can_scan($assigned)) return self::error('atlas_forbidden','You are not assigned to this occurrence.','شما برای پذیرش این زمان اجرا تعیین نشده‌اید.',403);return self::transaction(function() use ($body,$parts,$wpdb) { $hash=hash('sha256',$body['reference']);$key=$body['idempotency_key'];$prior=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.self::table('scan_keys').' WHERE actor_id=%d AND idem_key=%s FOR UPDATE',get_current_user_id(),$key));if ($prior) return hash_equals($prior->request_hash,$hash)?json_decode($prior->response,true):self::error('atlas_idempotency_conflict','Scan request key was reused.','کلید درخواست پذیرش دوباره استفاده شده است.',409);$booking=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.DB::table('bookings').' WHERE id=%s FOR UPDATE',$parts[2]));$occ=self::occurrence($parts[1]);$data=$occ?json_decode($occ->payload,true):[];if (!$booking||!$occ||!self::can_scan($occ)||(int)$booking->offer_id!==(int)$occ->offer_id||$booking->status!=='confirmed'||$occ->state!=='scheduled'||(int)$parts[3]<1||(int)$parts[3]>(int)$booking->quantity||DB::now()<($data['checkin_open_at']??'')||DB::now()>=($data['checkin_close_at']??'')) return self::error('atlas_event_checkin_closed','Confirmed attendee and open check-in window required.','شرکت‌کننده تأییدشده و مهلت پذیرش باز لازم است.',409);$table=$wpdb->prefix.'atlas_event_checkins';$insert=$wpdb->query($wpdb->prepare("INSERT IGNORE INTO $table (booking_id,attendee_index,offer_id,checked_by,checked_at) VALUES (%s,%d,%d,%d,%s)",$booking->id,(int)$parts[3],$occ->offer_id,get_current_user_id(),DB::now()));if ($insert===false) throw new RuntimeException('checkin');$result=['booking_id'=>$booking->id,'attendee_index'=>(int)$parts[3],'status'=>$insert===1?'checked_in':'already_checked_in'];if (!$wpdb->insert(self::table('scan_keys'),['actor_id'=>get_current_user_id(),'idem_key'=>$key,'request_hash'=>$hash,'response'=>wp_json_encode($result)])) throw new RuntimeException('key');self::audit((int)$occ->org_id,'event.scan',$booking->id);return $result; });
    }
    public static function permission($request) { return is_user_logged_in()&&wp_verify_nonce((string)$request->get_header('X-WP-Nonce'),'wp_rest'); }
    private static function response($data) { if (is_wp_error($data)) return $data;$response=new WP_REST_Response($data);$response->header('Cache-Control','private, no-store');return $response; }
    public static function routes() {
        foreach (['event-programs'=>'programs','event-occurrences'=>'occurrences'] as $route=>$type) register_rest_route('agency/v1','/'.$route,['methods'=>'GET','permission_callback'=>[__CLASS__,'permission'],'callback'=>static fn($r)=>self::response(self::listing($type,$r->get_param('page')?:1))]);
        register_rest_route('agency/v1','/event-programs',['methods'=>'POST','permission_callback'=>[__CLASS__,'permission'],'callback'=>static function($r) { $body=$r->get_json_params();return self::response(is_array($body)?self::save_program($body):self::error('atlas_invalid_event','Object required.','اطلاعات ساختاری لازم است.')); }]);
        register_rest_route('agency/v1','/event-programs/(?P<id>[a-f0-9-]{36})/transition',['methods'=>'POST','permission_callback'=>[__CLASS__,'permission'],'callback'=>static function($r) { $body=$r->get_json_params();return self::response(is_array($body)?self::transition_program($r['id'],$body):self::error('atlas_invalid_event','Object required.','اطلاعات ساختاری لازم است.')); }]);
        register_rest_route('agency/v1','/event-occurrences',['methods'=>'POST','permission_callback'=>[__CLASS__,'permission'],'callback'=>static function($r) { $body=$r->get_json_params();return self::response(is_array($body)?self::save_occurrence($body):self::error('atlas_invalid_event','Object required.','اطلاعات ساختاری لازم است.')); }]);
        register_rest_route('agency/v1','/event-occurrences/(?P<id>[a-f0-9-]{36})',['methods'=>'GET','permission_callback'=>'__return_true','callback'=>static function($r) { $result=self::public_occurrence($r['id']);if (is_wp_error($result)) return $result;$response=new WP_REST_Response($result);$response->header('Cache-Control','no-store');return $response; }]);
        register_rest_route('agency/v1','/event-occurrences/(?P<id>[a-f0-9-]{36})/transition',['methods'=>'POST','permission_callback'=>[__CLASS__,'permission'],'callback'=>static function($r) { $body=$r->get_json_params();return self::response(is_array($body)?self::transition_occurrence($r['id'],$body):self::error('atlas_invalid_event','Object required.','اطلاعات ساختاری لازم است.')); }]);
        register_rest_route('agency/v1','/event-occurrences/(?P<id>[a-f0-9-]{36})/waitlist',['methods'=>'POST','permission_callback'=>[__CLASS__,'permission'],'callback'=>static fn($r)=>self::response(self::join_waitlist($r['id']))]);
        register_rest_route('agency/v1','/event-waitlist/(?P<id>[a-f0-9-]{36})/invite',['methods'=>'POST','permission_callback'=>[__CLASS__,'permission'],'callback'=>static function($r) { $body=$r->get_json_params();return self::response(is_array($body)?self::invite($r['id'],$body):self::error('atlas_invalid_event','Object required.','اطلاعات ساختاری لازم است.')); }]);
        register_rest_route('agency/v1','/event-waitlist/(?P<id>[a-f0-9-]{36})/withdraw',['methods'=>'POST','permission_callback'=>[__CLASS__,'permission'],'callback'=>static fn($r)=>self::response(self::withdraw($r['id']))]);
        register_rest_route('agency/v1','/event-occurrences/(?P<id>[a-f0-9-]{36})/exception',['methods'=>'POST','permission_callback'=>[__CLASS__,'permission'],'callback'=>static function($r) { $body=$r->get_json_params();return self::response(is_array($body)?self::create_exception($r['id'],$body):self::error('atlas_invalid_event','Object required.','اطلاعات ساختاری لازم است.')); }]);
        register_rest_route('agency/v1','/event-notices',['methods'=>'GET','permission_callback'=>[__CLASS__,'permission'],'callback'=>static fn($r)=>self::response(['items'=>self::notices($r->get_param('page')?:1),'page'=>max(1,(int)($r->get_param('page')?:1)),'limit'=>25])]);
        register_rest_route('agency/v1','/events/attendee-references/(?P<id>[a-f0-9-]{36})',['methods'=>'GET','permission_callback'=>[__CLASS__,'permission'],'callback'=>static fn($r)=>self::response(self::credentials($r['id']))]);
        register_rest_route('agency/v1','/events/attendance-sync',['methods'=>'POST','permission_callback'=>[__CLASS__,'permission'],'callback'=>static function($r) { $body=$r->get_json_params();if (!is_user_logged_in()||!current_user_can('atlas_manage_records')) return self::error('atlas_forbidden','Assigned check-in access required.','دسترسی کارکنان پذیرش لازم است.',403);if (!is_array($body)||array_diff(array_keys($body),['scans'])||!is_array($body['scans']??null)||!array_is_list($body['scans'])||count($body['scans'])<1||count($body['scans'])>50) return self::error('atlas_invalid_event','Use a batch of one to fifty scans.','بسته یک تا پنجاه شناسه پذیرش مجاز است.');$out=[];foreach ($body['scans'] as $scan) { $result=is_array($scan)?self::scan($scan):self::error('atlas_invalid_event','Invalid scan.','شناسه پذیرش معتبر نیست.');$out[]=is_wp_error($result)?['error'=>$result->get_error_code(),'message'=>$result->get_error_message()]:$result; }return self::response(['items'=>$out]); }]);
    }
