    public static function booking_fields($html,$offer) {
        $occ=self::for_offer($offer['id']);if (!$occ) return $html;$public=self::public_occurrence($occ->id);if (is_wp_error($public)) return $html.'<p role="status">'.esc_html(self::t('Event admission unavailable.','پذیرش رویداد در دسترس نیست.')).'</p>';$p=$public['program'];
        $html.='<fieldset data-event-options><legend>'.esc_html(self::t('Event registration options','گزینه‌های ثبت‌نام رویداد')).'</legend><label>'.esc_html(self::t('Ticket tier — price per attendee (IRR)','رده بلیت — قیمت برای هر شرکت‌کننده (ریال)')).'<select name="event_tier" data-atlas-booking-option>';foreach ($public['resources'] as $r) if ($r['kind']==='tier') $html.='<option value="'.esc_attr($r['code']).'">'.esc_html(self::label($r).($r['kind']==='session'?' · '.$r['starts_at'].' – '.$r['ends_at'].' UTC':'').' · '.$r['unit_amount_irr'].' IRR · '.self::t('remaining ','باقی‌مانده ').$r['remaining']).'</option>';$html.='</select></label>';
        foreach (['session'=>self::t('Sessions','جلسه‌ها'),'addon'=>self::t('Optional services, per attendee','خدمات اختیاری برای هر شرکت‌کننده')] as $kind=>$label) { $html.='<fieldset><legend>'.esc_html($label).'</legend>';foreach ($public['resources'] as $r) if ($r['kind']===$kind) $html.='<label><input type="checkbox" name="event_'.($kind==='session'?'sessions':'addons').'[]" data-atlas-booking-option value="'.esc_attr($r['code']).'"'.($r['required']?' checked required':'').'>'.esc_html(self::label($r).($r['kind']==='session'?' · '.$r['starts_at'].' – '.$r['ends_at'].' UTC':'').' · '.$r['unit_amount_irr'].' IRR · '.self::t('remaining ','باقی‌مانده ').$r['remaining']).'</label>';$html.='</fieldset>'; }
        $waiver=self::t($p['waiver_en']?:$p['waiver_fa'],$p['waiver_fa']?:$p['waiver_en']);$html.='<p>'.nl2br(esc_html($waiver)).'</p><input type="hidden" name="event_waiver_version" data-atlas-booking-option value="'.esc_attr($p['waiver_version']).'"><label><input type="checkbox" name="event_waiver_accepted" data-atlas-booking-option data-value-type="bool" required>'.esc_html(self::t('I accept waiver version ','نسخه رضایت‌نامه را می‌پذیرم: ').$p['waiver_version']).'</label><p>'.esc_html(self::t('One selected option applies to each attendee in this reservation. Dietary/medical details are not collected here.','هر گزینه انتخاب‌شده برای همه شرکت‌کنندگان این رزرو اعمال می‌شود. اطلاعات پزشکی یا رژیم غذایی اینجا جمع‌آوری نمی‌شود.')).'</p>';
        foreach (['event_invitation','event_exception'] as $name) if (isset($_GET[$name])&&self::uuid($_GET[$name])&&($name!=='event_exception'||self::agency())) $html.='<input type="hidden" name="'.esc_attr($name).'" data-atlas-booking-option value="'.esc_attr($_GET[$name]).'">';return $html.'</fieldset>';
    }
    public static function offer_details($html,$offer) {
