        foreach (['code'=>self::t('Stable option code','کد ثابت گزینه'),'name_en'=>self::t('English label','عنوان انگلیسی'),'name_fa'=>self::t('Persian label','عنوان فارسی'),'capacity'=>self::t('Explicit capacity','ظرفیت مشخص'),'unit_amount_irr'=>self::t('Exact integer IRR per attendee; tier is base price, session must be 0','ریال صحیح برای هر نفر؛ رده قیمت پایه است و جلسه باید ۰ باشد'),'starts_at'=>self::t('Session starts (UTC ISO; session only)','شروع جلسه (UTC ISO؛ فقط جلسه)'),'ends_at'=>self::t('Session ends (UTC ISO; session only)','پایان جلسه (UTC ISO؛ فقط جلسه)')] as $key=>$label) $html.=self::field('resources['.$index.']['.$key.']',$label,in_array($key,['starts_at','ends_at'],true)&&!empty($r[$key])?self::iso($r[$key]):($r[$key]??''),in_array($key,['capacity','unit_amount_irr'],true)?'number':'text',false);
        return $html.'<label><input type="checkbox" name="resources['.$index.'][required]" value="1"'.checked(!empty($r['required']),true,false).'>'.esc_html(self::t('Required session/add-on (tiers are selected individually)','جلسه یا خدمت الزامی (رده‌ها جداگانه انتخاب می‌شوند)')).'</label><button type="button" data-remove-event-resource>'.esc_html(self::t('Remove option','حذف گزینه')).'</button></fieldset>';
