        if (isset($body['checkin_staff'])&&is_string($body['checkin_staff'])) { $staff=trim($body['checkin_staff']);$body['checkin_staff']=$staff===''?[]:array_map(static fn($value)=>ctype_digit(trim($value))?(int)trim($value):$value,explode(',',$staff)); }if (isset($body['resources'])&&is_array($body['resources'])) { $body['resources']=array_values($body['resources']);foreach ($body['resources'] as &$r) if (is_array($r)) { foreach (['capacity','unit_amount_irr'] as $key) if (isset($r[$key])&&is_string($r[$key])&&ctype_digit($r[$key])&&strlen($r[$key])<=18) $r[$key]=(int)$r[$key];$r['required']=isset($r['required']); }unset($r); }
