        switch ($operation) {case 'program_save':$result=self::save_program($body);break;case 'program_transition':$result=self::transition_program($id,$body);break;case 'occurrence_save':$result=self::save_occurrence($body);break;case 'occurrence_transition':$result=self::transition_occurrence($id,$body);break;case 'invite':$result=self::invite($id,$body);break;case 'exception':$result=self::create_exception($id,$body);break;case 'waitlist_join':$result=self::join_waitlist($id);break;case 'waitlist_withdraw':$result=self::withdraw($id);break;default:$result=self::error('atlas_invalid_event','Unknown operation.','عملیات ناشناخته است.'); }
